const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  try {
    // 1. Geometry & Time Definitions (Great Lakes broad bounding box)
    const geom = ee.Geometry.Polygon(
      [[[-93.5, 40.5], [-93.5, 49.8], [-74.5, 49.8], [-74.5, 40.5], [-93.5, 40.5]]],
      null,
      false
    );
    const baseStart = '2016-02-11';
    const baseEnd = '2016-02-12';

    // Helper: get MODIS Terra/Aqua collections by version and date
    function getCollections(version, start, end) {
      const terra = ee.ImageCollection(`MODIS/${version}/MOD09GA`).filterDate(start, end).filterBounds(geom);
      const aqua = ee.ImageCollection(`MODIS/${version}/MYD09GA`).filterDate(start, end).filterBounds(geom);
      return { terra, aqua, version };
    }

    // Helper: union valid/cloudy from a collection (OR across images)
    function unionCloudFromCollection(col) {
      const processed = col.map(function (img) {
        const state = img.select('state_1km');
        const bits01 = state.bitwiseAnd(3); // bits 0-1: cloud state
        const valid = bits01.neq(3).rename('valid'); // exclude 'not set'
        const cloudy = bits01.eq(1).or(bits01.eq(2)).rename('cloudy'); // cloudy or mixed -> cloudy
        return ee.Image.cat(valid, cloudy).uint8();
      });
      return processed.size().gt(0).conditional(ee.ImageCollection(processed).max(), null);
    }

    // Attempt chain: v061 exact day -> v006 exact day -> v061 3-day window
    const attempts = [
      { ver: '061', start: baseStart, end: baseEnd, label: '061 day' },
      { ver: '006', start: baseStart, end: baseEnd, label: '006 day' },
      { ver: '061', start: '2016-02-10', end: '2016-02-13', label: '061 3-day' }
    ];

    let chosen = null;
    let sizes = null;

    for (const att of attempts) {
      const cols = getCollections(att.ver, att.start, att.end);
      const terraSize = await cols.terra.size().getInfo();
      const aquaSize = await cols.aqua.size().getInfo();
      if (terraSize > 0 || aquaSize > 0) {
        chosen = { ...att, cols };
        sizes = { terra: terraSize, aqua: aquaSize };
        break;
      }
    }

    if (!chosen) {
      console.log('Terra images: 0');
      console.log('Aqua images: 0');
      console.log('<answer>C1</answer>');
      return;
    }

    // Build union per platform
    const terraImg = sizes.terra > 0 ? unionCloudFromCollection(chosen.cols.terra) : null;
    const aquaImg = sizes.aqua > 0 ? unionCloudFromCollection(chosen.cols.aqua) : null;

    // Combine Terra and Aqua (OR)
    let combined = null;
    if (terraImg && aquaImg) {
      const valid = ee.Image(terraImg).select('valid').max(ee.Image(aquaImg).select('valid')).rename('valid');
      const cloudy = ee.Image(terraImg).select('cloudy').max(ee.Image(aquaImg).select('cloudy')).rename('cloudy');
      combined = ee.Image.cat(valid, cloudy);
    } else if (terraImg) {
      combined = terraImg;
    } else if (aquaImg) {
      combined = aquaImg;
    } else {
      console.log(`Terra images: ${sizes.terra}`);
      console.log(`Aqua images: ${sizes.aqua}`);
      console.log('<answer>C2</answer>');
      return;
    }

    // Reduce over region to get valid and cloudy pixel counts
    const sums = await combined.reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: geom,
      scale: 1000,
      maxPixels: 1e9
    }).getInfo();

    const validSum = sums ? sums.valid : null;
    const cloudySum = sums ? sums.cloudy : null;

    if (validSum === null || cloudySum === null) {
      console.log(`Terra images: ${sizes.terra}`);
      console.log(`Aqua images: ${sizes.aqua}`);
      console.log('<answer>C3</answer>');
      return;
    }

    if (validSum === 0) {
      console.log(`Terra images: ${sizes.terra}`);
      console.log(`Aqua images: ${sizes.aqua}`);
      console.log('Valid pixels (1km): 0');
      console.log('<answer>C2</answer>');
      return;
    }

    const cloudFrac = cloudySum / validSum;
    if (!isFinite(cloudFrac)) {
      console.log(`Terra images: ${sizes.terra}`);
      console.log(`Aqua images: ${sizes.aqua}`);
      console.log('<answer>C3</answer>');
      return;
    }

    const cloudPct = cloudFrac * 100;

    // Print concise evidence
    console.log(`Terra images: ${sizes.terra} (ver ${chosen.ver}, window ${chosen.start} to ${chosen.end})`);
    console.log(`Aqua images: ${sizes.aqua} (ver ${chosen.ver}, window ${chosen.start} to ${chosen.end})`);
    console.log(`Valid pixels (1km): ${Math.round(validSum)}`);
    console.log(`Cloudy pixels: ${Math.round(cloudySum)}`);
    console.log(`Cloud fraction: ${cloudPct.toFixed(2)}%`);

    // Decision: clouds present if >= 1% of valid pixels cloudy
    const answer = cloudPct >= 1.0 ? 'A' : 'B';
    console.log(`<answer>${answer}</answer>`);
  } catch (err) {
    console.log('<answer>D</answer>');
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
